import Testing
@testable import Utilities

@Suite("withAsyncTeardown — SE-0493 placeholder (#280)")
struct AsyncTeardownTests {

    private actor Recorder {
        private(set) var events: [String] = []
        func record(_ event: String) { events.append(event) }
    }

    @Test("teardown runs after a successful body, and the result is returned")
    func teardownRunsOnSuccess() async throws {
        let recorder = Recorder()

        let result = await withAsyncTeardown {
            await recorder.record("body")
            return 42
        } teardown: {
            await recorder.record("teardown")
        }

        #expect(result == 42)
        #expect(await recorder.events == ["body", "teardown"], "teardown must run after the body completes")
    }

    @Test("teardown runs when the body throws, and the error is rethrown")
    func teardownRunsOnThrow() async {
        struct BodyError: Error {}
        let recorder = Recorder()

        await #expect(throws: BodyError.self) {
            try await withAsyncTeardown {
                await recorder.record("body")
                throw BodyError()
            } teardown: {
                await recorder.record("teardown")
            }
        }

        #expect(await recorder.events == ["body", "teardown"], "teardown must run before the error propagates")
    }

    @Test("teardown runs when the body is cancelled mid-flight")
    func teardownRunsOnCancellation() async throws {
        let recorder = Recorder()

        let task = Task {
            try await withAsyncTeardown {
                await recorder.record("body-start")
                try await Task.sleep(for: .seconds(60))
                await recorder.record("body-end-unreachable")
            } teardown: {
                await recorder.record("teardown")
            }
        }

        // Let the body reach its sleep before cancelling.
        while await recorder.events.isEmpty {
            try await Task.sleep(for: .milliseconds(1))
        }
        task.cancel()

        await #expect(throws: CancellationError.self) { try await task.value }
        #expect(
            await recorder.events == ["body-start", "teardown"],
            "teardown must run even when cancellation aborts the body"
        )
    }

    @Test("teardown itself completes inside an already-cancelled task")
    func teardownCompletesUnderCancellation() async {
        let recorder = Recorder()

        let task = Task {
            await withAsyncTeardown {
                task_local_noop()
            } teardown: {
                // Cooperative cancellation must not skip teardown's own awaits.
                await recorder.record("teardown-ran")
            }
        }
        task.cancel()
        await task.value

        #expect(await recorder.events == ["teardown-ran"])
    }

    private func task_local_noop() {}
}

