/// Once the toolchain gains SE-0493, call sites become a mechanical rewrite:
///
///     await withAsyncTeardown { try await work() } teardown: { await close() }
///     // becomes
///     defer { await close() }
///     try await work()
///
/// - Parameters:
///   - isolation: Inherits the caller's actor isolation so neither closure
///     hops executors and non-`Sendable` results flow through unchanged.
///   - body: The scoped work.
///   - teardown: Cleanup that must run regardless of how `body` exits.
/// - Returns: The value produced by `body`.
/// - Throws: Whatever `body` throws, after `teardown` has completed.
public func withAsyncTeardown<T>(
    isolation: isolated (any Actor)? = #isolation,
    _ body: () async throws -> T,
    teardown: () async -> Void
) async rethrows -> T {
    do {
        let result = try await body()
        await teardown()
        return result
    } catch {
        await teardown()
        throw error
    }
}

