/// every buffer this specific tap delivers to `inputFormat`, for the
/// lifetime of that tap — a new rate is only ever observed via a new
/// `.AVAudioEngineConfigurationChange` notification, which is what drives
/// `handleTapConfigurationChange()` (and thus a fresh `installConverterTap`
/// call with the new rate) above. `MicCaptureActorRouteChange`'s equivalent
/// tap (#49) relies on the same guarantee and has no such check either.
func installConverterTap(
    inputFormat: AVAudioFormat,
    targetFormat: AVAudioFormat,
    converter: AVAudioConverter,
    tapT0: UInt64,
    continuation: AsyncStream<DomainAudioBuffer>.Continuation,
    writer: WAVWriter,
    configuration: AudioConfiguration
) {
    guard let newEngine = engine else { return }

    let errorTracker = ConverterErrorTracker(
        failureThreshold: converterFailureThreshold,
        onFailure: { [weak self] msg in
            self?.logger.error("\(msg, privacy: .private)")
        }
    )

    newEngine.inputNode
        .installTap(onBus: 0, bufferSize: 4096, format: inputFormat) { [weak self] inBuffer, when in
            guard let self else { return }

            let ratio = configuration.sampleRate / inputFormat.sampleRate
            let outFrameCount = AVAudioFrameCount(Double(inBuffer.frameLength) * ratio)
            guard let outBuffer = AVAudioPCMBuffer(pcmFormat: targetFormat, frameCapacity: outFrameCount)
            else { return }

            let consumed = TapConverterInputFlag()
            var error: NSError?
            converter.convert(to: outBuffer, error: &error) { _, status in
                guard !consumed.value else {
                    status.pointee = .noDataNow
                    return nil
                }
                consumed.value = true
                status.pointee = .haveData
                return inBuffer
            }

            if let error {
                if errorTracker.recordFailure(error) {
                    continuation.finish()
                }
                return
            }

            guard let channelData = outBuffer.floatChannelData?[0] else { return }
            let floatArray = Array(UnsafeBufferPointer(start: channelData, count: Int(outBuffer.frameLength)))
            guard !floatArray.isEmpty else { return }

            // Reset consecutive failure counter on successful conversion
            errorTracker.recordSuccess()

            let ts = MachClock.ticksToSeconds(when.hostTime &- tapT0)
            let domainBuffer = DomainAudioBuffer(
                sampleRate: configuration.sampleRate,
                channelCount: configuration.channels,
                samples: floatArray,
                timestamp: ts
            )

