import Domain
import Foundation
import GRDB
import Logging
import Utilities

public actor GRDBStorageActor {
    public let dbPool: any DatabaseWriter & Sendable
    private let databaseURL: URL?
    let logger = AppLogger.for(category: "GRDBStorage")

    public init(databasePath: URL?) throws {
        self.databaseURL = databasePath
        if let path = databasePath {
            try FileManager.default.createDirectory(
                at: path.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            dbPool = try DatabasePool(path: path.path)
        } else {
            dbPool = try DatabaseQueue()
        }
        try GRDBMigrations.migrator().migrate(dbPool)
        if let path = databasePath {
            try FileManager.default.setAttributes(
                [.posixPermissions: 0o600 as NSNumber],
                ofItemAtPath: path.path
            )
        }
    }

    public init() throws {
        let dbDir = Directories.appSupport
        try Directories.ensureDirectory(at: dbDir)
        let dbURL = dbDir.appendingPathComponent(AppConstants.Paths.databaseFileName)
        try self.init(databasePath: dbURL)
    }

    // MARK: - Teardown

    /// Explicitly closes the underlying database pool, flushing the WAL.
    /// #280: called from app teardown so the process no longer exits with
    /// open connections. Any access after close throws.
    public func close() async throws {
        do {
            try dbPool.close()
        } catch {
            logger.error("Database close failed: \(error)")
            throw StorageError.writeFailed(underlying: error)
        }
    }

    // MARK: - Backup

    public func backupDatabase(to destination: URL) async throws {
        try await dbPool.write { db in
            try db.execute(sql: "PRAGMA wal_checkpoint(TRUNCATE)")
        }
        guard let sourcePath = databaseURL else {
            throw StorageError.writeFailed(underlying: nil)
        }
        let fm = FileManager.default
        if fm.fileExists(atPath: destination.path) {
            try fm.removeItem(at: destination)
        }
        try fm.copyItem(at: sourcePath, to: destination)
    }

    public func backupDatabase(source: URL, to destination: URL) async throws {
        let fm = FileManager.default
        if fm.fileExists(atPath: destination.path) {
            try fm.removeItem(at: destination)
        }
        try fm.copyItem(at: source, to: destination)
    }
}

import Domain
import Foundation
@testable import StorageInfrastructure
import Testing

/// #280: explicit async teardown for the GRDB pool. Before this API the pool
/// was never closed — the process just died with connections open.
@Suite("GRDBStorageActor.close (#280)")
struct GRDBStorageCloseTests {

    @Test("close() succeeds on a live store")
    func closeSucceeds() async throws {
        let storage = try GRDBStorageActor(databasePath: nil)
        try await storage.close()
    }

    @Test("database access after close() throws a StorageError instead of trapping")
    func accessAfterCloseThrows() async throws {
        let storage = try GRDBStorageActor(databasePath: nil)
        try await storage.close()

        await #expect(throws: StorageError.self) {
            _ = try await storage.telemetryRowCount()
        }
    }
}

