@preconcurrency import AVFoundation
import Domain
import Foundation
import Logging
import OSLog

// MARK: - MicTapBridge

// Receives raw AVAudioPCMBuffers on the real-time audio thread, converts them
// to 16 kHz mono Float32, and forwards TaggedAudioBuffers to the stream.
//
// Marked @unchecked Sendable because:
// - This class is private and never escapes MicCaptureActor's scope.
// - `process(_:)` is invoked exclusively from the single AVAudioEngine tap
//   queue; AVAudioConverter is never shared across threads concurrently.
// - After initialisation all stored state is effectively read-only except
//   `sampleBuffer`, which is mutated only on the single tap queue thread.

/// Internal (not private) so MicCaptureActorRouteChange.swift extension can construct it.
final class MicTapBridge: @unchecked Sendable {
    private let continuation: AsyncThrowingStream<TaggedAudioBuffer, Error>.Continuation
    private let converter: AVAudioConverter
    private let targetFormat: AVAudioFormat
    private let maxFrameCapacity: AVAudioFrameCount
    private let sessionStartTick: UInt64
    private let signposter = OSSignposter(subsystem: "app.the-record", category: "Performance")
    private let logger = AppLogger.for(category: "MicTapBridge")
    private let converterFailureThreshold = 5

    private var sampleBuffer: [Float]
    private let outBuffer: AVAudioPCMBuffer
    private var consecutiveConverterFailures = 0

    init(
        continuation: AsyncThrowingStream<TaggedAudioBuffer, Error>.Continuation,
        converter: AVAudioConverter,
        targetFormat: AVAudioFormat,
        maxFrameCapacity: AVAudioFrameCount,
        sessionStartTick: UInt64
    ) {
        self.continuation = continuation
        self.converter = converter
        self.targetFormat = targetFormat
        self.maxFrameCapacity = maxFrameCapacity
        self.sessionStartTick = sessionStartTick
        self.sampleBuffer = [Float](repeating: 0, count: Int(maxFrameCapacity))
        self.outBuffer = AVAudioPCMBuffer(pcmFormat: targetFormat, frameCapacity: maxFrameCapacity)!
    }

    func process(_ pcmBuffer: AVAudioPCMBuffer, when: AVAudioTime) {
        let state = signposter.beginInterval("MicTapProcess")
        defer { signposter.endInterval("MicTapProcess", state) }

        outBuffer.frameLength = 0

        let consumed = ConverterInputFlag()
        var error: NSError?
        converter.convert(to: outBuffer, error: &error) { _, status in
            guard !consumed.value else {
                status.pointee = .noDataNow
                return nil
            }
            consumed.value = true
            status.pointee = .haveData
            return pcmBuffer
        }

        if let error {
            handleConverterError(error)
            return
        }

        guard outBuffer.frameLength > 0,
              let channelData = outBuffer.floatChannelData
        else { return }

        // Reset consecutive failure counter on successful conversion
        consecutiveConverterFailures = 0

        let frameLen = Int(outBuffer.frameLength)

        sampleBuffer.withUnsafeMutableBufferPointer { ptr in
            if let base = ptr.baseAddress {
                base.update(from: channelData[0], count: frameLen)
            }
        }

        let samples = Array(sampleBuffer.prefix(frameLen))

        let timestamp = MachClock.ticksToSeconds(when.hostTime &- sessionStartTick)
        let audioBuf = AudioBuffer(
            sampleRate: targetFormat.sampleRate,
            channelCount: 1,
            samples: samples,
            timestamp: timestamp
        )
        let tagged = TaggedAudioBuffer(
            buffer: audioBuf,
            track: .microphone,
            timestamp: timestamp
        )
        if case .dropped = continuation.yield(tagged) {
            logger.warning("Microphone audio buffer dropped — stream full, frames lost")
        }
    }

    /// Handles AVAudioConverter errors by logging them and tracking consecutive failures.
    /// After `converterFailureThreshold` consecutive failures, finishes the stream with error.
    private func handleConverterError(_ error: NSError) {
        self.consecutiveConverterFailures += 1
        logger.error(
            "AVAudioConverter error (consecutive count: \(self.consecutiveConverterFailures)): \(error.localizedDescription, privacy: .private)"
        )

        if self.consecutiveConverterFailures >= self.converterFailureThreshold {
            logger.error(
                "Converter failures reached threshold (\(self.converterFailureThreshold)), terminating stream"
            )
            self.consecutiveConverterFailures = 0
            continuation.finish(throwing: error)
        }
    }
}

