    // was calling append(_:) from SCStream's concurrent sampleHandlerQueue without
    // synchronization, causing lost counter increments (48000 → 47520).
    private let queue = DispatchQueue(label: "app.the-record.wavwriter", qos: .userInitiated)

    private let fileHandle: FileHandle
    private let sampleRate: Int
    private let channels: Int
