import Domain
import Foundation
import Logging
import Utilities

// MARK: - WAVCleanedAudioSink

/// Infrastructure implementation of ``CleanedAudioSink`` that persists AEC-cleaned
/// microphone audio to a WAV file inside the session's recording directory.
///
/// ## File naming
/// `<iso8601-date>-mic-cleaned.wav` — the `mic-cleaned` suffix distinguishes this
/// file from the system audio WAV written by `CoreAudioTapCaptureActor`.
///
/// ## Format
/// 16 kHz, mono, 16-bit PCM — matches `AECProcessorActor` output exactly (INV-003).
///
/// ## Thread Safety (ISO-001)
/// `WAVCleanedAudioSink` is `@unchecked Sendable`. All mutable state is protected
/// by the same `DispatchQueue` strategy as `WAVWriter`:
/// - `_writer`, `_failed`, `_metadata` accessed only on `queue`.
/// - `append(_:)` dispatches async to `queue` — fire-and-forget, no audio-path block.
/// - `finalize()` awaits the queue to drain all pending appends before header fix-up.
///
/// ## Failure Handling (SAFE-001, OBS-002)
/// If `WAVWriter` init throws, `_failed` is set immediately and one error is logged.
/// All subsequent `append` calls see `_failed == true` and become no-ops.
/// `finalize()` returns `nil` when the writer was never initialized.
///
/// ## Idempotency (IDEM-002)
/// The first `finalize()` sets `_metadata` and closes the file.
/// Subsequent calls return `_metadata` without touching the file.
///
/// ## Empty-file contract (BOUND-003)
/// `finalize()` with zero appended frames produces a valid 44-byte WAV header
/// (no PCM payload). `AudioFileLoader.loadSamples` will throw `audioTooShort`
/// which is correct behaviour — callers must guard for it.
public final class WAVCleanedAudioSink: CleanedAudioSink, @unchecked Sendable {
    // MARK: - Private State

    private let queue = DispatchQueue(label: "app.the-record.cleaned-audio-sink", qos: .userInitiated)
    private let fileURL: URL
    private var _writer: WAVWriter?
    private var _failed = false
    private var _metadata: CleanedAudioSinkMetadata?
    private let logger = AppLogger.for(category: "CleanedAudioSink")

    // MARK: - Init

    /// Creates a new sink that will write into `recordingDirectory` using the
    /// same year/month sub-directory layout as `CoreAudioTapCaptureActor`.
    ///
    /// If the directory cannot be created or the `WAVWriter` cannot open the file,
    /// the sink enters a permanently-failed state and all `append` calls become no-ops.
    ///
    /// - Parameters:
    ///   - recordingDirectory: Root recording directory (e.g. `Directories.recordings`).
    ///   - sessionDate: Date used to compute the year/month sub-path and file name.
    public init(recordingDirectory: URL, sessionDate: Date) {
        let url = Self.makeFileURL(recordingDirectory: recordingDirectory, date: sessionDate)
        fileURL = url

        do {
            try Directories.ensureDirectory(at: url.deletingLastPathComponent())
            // Wire errorHandler so WAVWriter write failures mark the sink as failed
            // (F22/#202): subsequent appends become no-ops and finalize() returns nil,
            // preventing further writes to a broken file stream.
            _writer = try WAVWriter(url: url, sampleRate: 16000, channels: 1, errorHandler: { [weak self] error in
                guard let self else { return }
                self.queue.async {
                    self._failed = true
                    self.logger.error(
                        "WAVCleanedAudioSink write failed — sink disabled: \(String(describing: error), privacy: .private)"
                    )
                }
            })
        } catch {
            _failed = true
            logger.error(
                "WAVCleanedAudioSink init failed — sink disabled: \(String(describing: error), privacy: .private)"
            )
        }
    }

    // MARK: - CleanedAudioSink

    /// Appends AEC-cleaned microphone samples to the WAV file.
    ///
    /// Safe to call from any concurrency context. Dispatches async onto the serial
    /// queue — no blocking of the audio path. Silently discarded when the sink has
    /// failed or been finalized.
    public func append(_ buffer: TaggedAudioBuffer) {
        queue.async { [weak self] in
            guard let self, !self._failed, self._metadata == nil else { return }
            self._writer?.append(buffer.buffer.samples)
        }
    }

    /// Finalizes the WAV file and returns persisted file metadata.
    ///
    /// Waits for all pending `append` dispatches to drain, then delegates to
    /// `WAVWriter.finalize()` to fix the RIFF header with the correct sample count.
    ///
    /// - Returns: `CleanedAudioSinkMetadata` on success, or `nil` if the writer
    ///   failed at init time.
    public func finalize() async -> CleanedAudioSinkMetadata? {
        // Fast path: already finalized (IDEM-002).
        let alreadyDone: CleanedAudioSinkMetadata? = queue.sync { _metadata }
        if let alreadyDone { return alreadyDone }

        // Check whether init failed (no writer).
        let shouldAbort: Bool = queue.sync { _failed || _writer == nil }
        if shouldAbort { return nil }

        // Finalize the WAVWriter (drains queue via its own sync flush internally).
        guard let writer = queue.sync(execute: { _writer }) else { return nil }

        do {
            try await writer.finalize()
        } catch {
            logger.error(
                "WAVCleanedAudioSink.finalize() failed: \(String(describing: error), privacy: .private)"
            )
            return nil
        }

        let totalSamples = writer.totalSamplesWritten
        let duration = Double(totalSamples) / 16000.0

        let metadata = CleanedAudioSinkMetadata(
            fileURL: fileURL,
            duration: duration,
            sampleCount: totalSamples
        )

        queue.sync { _metadata = metadata }
        return metadata
    }

    // MARK: - Private Helpers

    /// Builds the output file URL using the same year/month layout as
    /// `CoreAudioTapCaptureActor.makeFileURL(for:)`, with `mic-cleaned` suffix.
    ///
    /// Example: `.../recordings/2026/06/<iso8601>-mic-cleaned.wav`
    static func makeFileURL(recordingDirectory: URL, date: Date) -> URL {
        let cal = Calendar.current
        let y = String(cal.component(.year, from: date))
        let m = String(format: "%02d", cal.component(.month, from: date))
        let name = date.formatted(.iso8601) + "-mic-cleaned.wav"
        return recordingDirectory
            .appendingPathComponent(y)
            .appendingPathComponent(m)
            .appendingPathComponent(name)
    }
}

