import AudioToolbox
@preconcurrency import AVFAudio
@preconcurrency import AVFoundation
import CoreAudio
import Domain
import Foundation
import Logging

// MARK: - Route-change handling (#244)

/// Fixes the diarization root cause: `CoreAudioTapCaptureActor` used to read
/// the tap's input format once at `setupAggregateAndEngine` time and never
/// revisit it. A mid-session sample-rate change (route/device switch) left the
/// `AVAudioConverter` assuming a stale input rate, silently time-stretching the
/// recorded WAV by 1.6-1.9x and corrupting every downstream transcript/
/// diarization timestamp.
///
/// Mirrors the `MicCaptureActorRouteChange.handleConfigurationChange()` pattern
/// (#49): observe `.AVAudioEngineConfigurationChange`, remove the stale tap,
/// re-read the input format, rebuild the converter, reinstall the tap, restart
/// the engine — reusing the existing continuation/writer/tapT0 so the recording
/// session is uninterrupted.
extension CoreAudioTapCaptureActor {
    /// Registers the config-change observer on `engine`. Removed in `cleanup()`.
    func registerRouteChangeObserver(engine: AVAudioEngine) {
        let observer = NotificationCenter.default.addObserver(
            forName: .AVAudioEngineConfigurationChange,
            object: engine,
            queue: nil
        ) { [weak self] _ in
            Task { await self?.handleTapConfigurationChange() }
        }
        routeChangeObserver = observer
    }

    /// Rebuilds the tap converter after a mid-session hardware reconfiguration.
    ///
    /// Reuses `streamContinuation`, `wavWriter`, and `tapT0` so the in-flight
    /// recording session keeps writing to the same file with a continuous
    /// timestamp epoch — only the input format and converter are rebuilt.
    func handleTapConfigurationChange() async {
        guard state == .recording,
              let eng = engine,
              let writer = wavWriter,
              let continuation = streamContinuation,
              let configuration = sessionConfiguration
        else { return }

        eng.inputNode.removeTap(onBus: 0)

        let newInputFormat = eng.inputNode.inputFormat(forBus: 0)
        guard newInputFormat.sampleRate > 0, newInputFormat.channelCount > 0 else {
            logger.error("Route change: new tap input format invalid — system audio capture cannot resume")
            await abortRouteChange()
            return
        }

        guard let targetFormat = AVAudioFormat(
            commonFormat: .pcmFormatFloat32,
            sampleRate: configuration.sampleRate,
            channels: AVAudioChannelCount(configuration.channels),
            interleaved: false
        ) else {
            logger.error("Route change: cannot rebuild target format")
            await abortRouteChange()
            return
        }

        guard let newConverter = AVAudioConverter(from: newInputFormat, to: targetFormat) else {
            logger.error("Route change: cannot rebuild converter from new tap input format")
            await abortRouteChange()
            return
        }

        installConverterTap(
            inputFormat: newInputFormat,
            targetFormat: targetFormat,
            converter: newConverter,
            tapT0: tapT0,
            continuation: continuation,
            writer: writer,
            configuration: configuration
        )

        do {
            try eng.start()
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "Route change handled — system tap resumed (sampleRate=\(newInputFormat.sampleRate, privacy: .private))"
                )
        } catch {
            logger.error(
                "Route change: failed to restart tap engine — \(String(reflecting: error), privacy: .public)"
            )
            await abortRouteChange()
        }
    }

    /// Tears down a mid-session route-change failure so the actor never gets
    /// stuck reporting `.recording` with a dead tap while capture has silently
    /// stopped (#223/#244).
    ///
    /// Mirrors `MicCaptureActorRouteChange.abortRouteChange(with:)`: finishes
    /// the stream continuation so any caller awaiting the buffer stream sees
    /// the session end instead of hanging forever, finalizes the WAV file the
    /// same way `stop()` does so its header reflects exactly what was
    /// captured instead of being left open/truncated, then reuses `cleanup()`
    /// — the same teardown `stop()` and `start()`'s catch block already
    /// perform — for engine/tap/aggregate-device resources and session
    /// bookkeeping.
    ///
    /// NOTE: internal (not private) so `CoreAudioTapRouteChangeTests` can call
    /// it directly — driving `handleTapConfigurationChange()`'s failure
    /// branches end-to-end requires a real `AVAudioEngine` with live input
    /// hardware, which this test target cannot rely on running headless.
    func abortRouteChange() async {
        streamContinuation?.finish()
        try? await wavWriter?.finalize()
        cleanup()
        state = .idle
    }

    /// Installs the resampling tap on `engine.inputNode`, wiring up conversion,
    /// error tracking, and WAV persistence. Shared by the initial `start()` setup
    /// and `handleTapConfigurationChange()`'s rebuild so both paths stay in sync.
    ///
    /// No per-buffer sample-rate re-check is needed here: `installTap(onBus:
    /// bufferSize:format:)`'s `format:` parameter makes AVFoundation coerce
    /// every buffer this specific tap delivers to `inputFormat`, for the
    /// lifetime of that tap — a new rate is only ever observed via a new
    /// `.AVAudioEngineConfigurationChange` notification, which is what drives
    /// `handleTapConfigurationChange()` (and thus a fresh `installConverterTap`
    /// call with the new rate) above. `MicCaptureActorRouteChange`'s equivalent
    /// tap (#49) relies on the same guarantee and has no such check either.
    func installConverterTap(
        inputFormat: AVAudioFormat,
        targetFormat: AVAudioFormat,
        converter: AVAudioConverter,
        tapT0: UInt64,
        continuation: AsyncStream<DomainAudioBuffer>.Continuation,
        writer: WAVWriter,
        configuration: AudioConfiguration
    ) {
        guard let newEngine = engine else { return }

        let errorTracker = ConverterErrorTracker(
            failureThreshold: converterFailureThreshold,
            onFailure: { [weak self] msg in
                self?.logger.error("\(msg, privacy: .private)")
            }
        )

        newEngine.inputNode
            .installTap(onBus: 0, bufferSize: 4096, format: inputFormat) { [weak self] inBuffer, when in
                guard let self else { return }

                let ratio = configuration.sampleRate / inputFormat.sampleRate
                let outFrameCount = AVAudioFrameCount(Double(inBuffer.frameLength) * ratio)
                guard let outBuffer = AVAudioPCMBuffer(pcmFormat: targetFormat, frameCapacity: outFrameCount)
                else { return }

                let consumed = TapConverterInputFlag()
                var error: NSError?
                converter.convert(to: outBuffer, error: &error) { _, status in
                    guard !consumed.value else {
                        status.pointee = .noDataNow
                        return nil
                    }
                    consumed.value = true
                    status.pointee = .haveData
                    return inBuffer
                }

                if let error {
                    if errorTracker.recordFailure(error) {
                        continuation.finish()
                    }
                    return
                }

                guard let channelData = outBuffer.floatChannelData?[0] else { return }
                let floatArray = Array(UnsafeBufferPointer(start: channelData, count: Int(outBuffer.frameLength)))
                guard !floatArray.isEmpty else { return }

                // Reset consecutive failure counter on successful conversion
                errorTracker.recordSuccess()

                let ts = MachClock.ticksToSeconds(when.hostTime &- tapT0)
                let domainBuffer = DomainAudioBuffer(
                    sampleRate: configuration.sampleRate,
                    channelCount: configuration.channels,
                    samples: floatArray,
                    timestamp: ts
                )
                if case .dropped = continuation.yield(domainBuffer) {
                    self.logger.warning("System audio buffer dropped — stream full, frames lost")
                }
                writer.append(floatArray)
            }
    }
}

