final class ConverterErrorTracker: Sendable {
    private let consecutiveFailures = Mutex(0)
    let failureThreshold: Int
    let onFailure: @Sendable (String) -> Void

    init(failureThreshold: Int, onFailure: @escaping @Sendable (String) -> Void) {
        self.failureThreshold = failureThreshold
        self.onFailure = onFailure
    }

    func recordFailure(_ error: NSError) -> Bool {
        let count = consecutiveFailures.withLock { value in
            value += 1
            return value
        }
        onFailure(
            "AVAudioConverter error (consecutive count: \(count)): \(error.localizedDescription)"
        )

        if count >= failureThreshold {
            onFailure("Converter failures reached threshold (\(failureThreshold)), terminating stream")
            consecutiveFailures.withLock { $0 = 0 }
            return true
        }
        return false
    }

    func recordSuccess() {
        consecutiveFailures.withLock { $0 = 0 }
    }
}

