// MARK: - Consecutive Failure Tests

@Suite("CoreAudioTapCaptureActorSupport")
struct CoreAudioTapCaptureActorSupportTests {
    /// #194: N consecutive conversion failures on the REAL `ConverterErrorTracker`
    /// (the class `CoreAudioTapCaptureActor` actually wires up around its converter tap)
    /// must terminate the stream instead of swallowing failures forever.
    @Test("Consecutive failures trigger stream termination")
    func consecutiveFailuresFinishesStreamWithCaptureFailed() async throws {
        let failureThreshold = 5
        // #281: onFailure is @Sendable now, so the collected messages live
        // behind a Mutex instead of a captured var.
        let messages = Mutex<[String]>([])
        let tracker = ConverterErrorTracker(failureThreshold: failureThreshold) { msg in
            messages.withLock { $0.append(msg) }
        }
        let sampleError = NSError(domain: "test.converter", code: -1)

        // Simulate N-1 consecutive failures (should not terminate)
        for i in 0 ..< failureThreshold - 1 {
            let shouldTerminate = tracker.recordFailure(sampleError)
            #expect(
                !shouldTerminate,
                "Stream should not terminate before threshold (iteration \(i))"
            )
        }

        // The Nth failure should trigger termination
        let shouldTerminate = tracker.recordFailure(sampleError)
        #expect(shouldTerminate, "Stream should terminate after threshold reached")

        // Verify counter is reset after termination
        #expect(tracker.consecutiveFailures == 0, "Counter should be reset after termination")
        #expect(messages.withLock { $0 }.contains { $0.contains("terminating stream") })
    }

    @Test("Single failure followed by success resets counter")
    func singleFailureFollowedBySuccessResetsCounter() async throws {
        let failureThreshold = 5
        let tracker = ConverterErrorTracker(failureThreshold: failureThreshold) { _ in }
        let sampleError = NSError(domain: "test.converter", code: -1)

        // Record one failure
        let shouldTerminate1 = tracker.recordFailure(sampleError)
        #expect(!shouldTerminate1, "Single failure should not trigger termination")
        #expect(tracker.consecutiveFailures == 1, "Counter should be 1 after first failure")

        // Record success (which should reset counter)
        tracker.recordSuccess()

        #expect(tracker.consecutiveFailures == 0, "Counter should reset to 0 after success")
    }

    @Test("Multiple failure cycles maintain independent counters")
    func multipleFailureCyclesIndependent() async throws {
        let failureThreshold = 3
        let tracker = ConverterErrorTracker(failureThreshold: failureThreshold) { _ in }
        let sampleError = NSError(domain: "test.converter", code: -1)

        // First cycle: 3 failures (should terminate)
        for _ in 0 ..< failureThreshold {
            _ = tracker.recordFailure(sampleError)
        }
        #expect(tracker.consecutiveFailures == 0, "Counter should reset after first termination cycle")

        // Second cycle: 2 failures (should not terminate)
        for _ in 0 ..< failureThreshold - 1 {
            let shouldTerminate = tracker.recordFailure(sampleError)
            #expect(!shouldTerminate, "Should not terminate in second cycle until threshold")
        }

        #expect(
            tracker.consecutiveFailures == failureThreshold - 1,
            "Counter should track failures correctly before threshold"
        )
    }
}

import Domain
import Foundation
import Logging
import speex

// MARK: - SpeexResources

/// Owns the two Speex C heap allocations so they are freed deterministically
/// in `deinit` — even if `stop()` is never called on the actor.
private final class SpeexResources {
    let echo: OpaquePointer
    let pp: OpaquePointer

    init?(frameSize: Int32, filterLength: Int32, sampleRate: Int32) {
        guard let e = speex_echo_state_init(frameSize, filterLength),
              let p = speex_preprocess_state_init(frameSize, sampleRate)
        else { return nil }
        // Link preprocessor to echo state for residual echo suppression.
        // speex_preprocess_ctl SPEEX_PREPROCESS_SET_ECHO_STATE stores the ptr
        // directly (st->echo_state = (SpeexEchoState*)ptr), so pass the opaque
        // pointer cast to UnsafeMutableRawPointer — not a pointer to a pointer.
        speex_preprocess_ctl(p, SPEEX_PREPROCESS_SET_ECHO_STATE, UnsafeMutableRawPointer(e))
        echo = e
        pp = p
    }

    deinit {
        speex_echo_state_destroy(echo)
        speex_preprocess_state_destroy(pp)
    }
}

// MARK: - AECProcessorActor

/// Applies SpeexDSP acoustic echo cancellation to mic audio using the far-end
/// (system audio) stream as the echo reference.
///
/// ## Thread Safety
/// All mutable state (`resources`, `stopped`) is isolated to the actor.
/// No callbacks or external threads access this state.
///
/// ## Error Translation
/// No external error types are thrown -- Speex operates via C function calls that
/// return output values. An uninitialized state (after `stop()`) causes pass-through
/// rather than an error.
///
/// ## Frame Sizing
/// Speex requires fixed-size Int16 frames. Input buffers are chunked into
/// `frameSize` windows; leftovers carry across calls in `remainder`.
///
/// ## Memory Safety
/// Speex C heap allocations are owned by `SpeexResources` and freed in its `deinit`,
/// guaranteeing no leak even if `stop()` is never called.
public actor AECProcessorActor: MicAECProcessor {
    private let aecQueue = DispatchSerialQueue(label: "app.the-record.aec", qos: .userInitiated)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        aecQueue.asUnownedSerialExecutor()
    }

    // MARK: - Private State

    /// Wraps the two Speex C allocations; `nil` after `stop()` or failed init.
    private var resources: SpeexResources?

    private let frameSize: Int32
    private let filterLength: Int32
    private let sampleRate: Int32

    private let logger = AppLogger.for(category: "AECProcessor")

    // MARK: - Pre-allocated frame buffers

    private var micInt16: [Int16]
    private var farInt16: [Int16]
    private var outInt16: [Int16]
    private var outFloat: [Float]

    // MARK: - Remainder buffer for inter-call chunking

    /// Carries sub-frame leftover samples from the previous call.
    /// Prepended to the next call's input so no samples are ever discarded.
    private var remainder: [Float] = []

    // MARK: - Diagnostic state (A6 / #245 — log-once guard for silent AEC output)
    //
    // The writer/persistence chain downstream of this actor is known-healthy
    // (see #244, #192, F11, F27, #223). If the mic-cleaned WAV is ever silent,
    // the cause enters upstream of the writer -- either here (AEC math) or in
    // how the far-end reference is sourced (RecordingStateViewModelStreaming).
    // This counter turns a silent-WAV incident into a discoverable log line
    // instead of a mystery: it does not fix any root cause, only makes one
    // class of it diagnosable in production logs.

    /// Consecutive processed Speex frames whose output RMS was near-zero while
    /// the corresponding mic input RMS was above `inputRMSThreshold`. Reset to
    /// zero whenever a frame does not meet both conditions. Not `private` so
    /// tests (`@testable import`) can assert on it directly.
    var consecutiveSilentOutputFrames = 0

    /// Set once `consecutiveSilentOutputFrames` first crosses
    /// `silentOutputWarningThreshold`, so the diagnostic warning fires exactly
    /// once per actor lifetime (until `stop()` resets it) rather than spamming
    /// once per 16ms frame.
    var hasLoggedSilentOutputWarning = false

    /// ~800ms of consecutive silent-despite-loud-input frames (50 * 16ms @ 256
    /// samples/16kHz) before the diagnostic warning is logged.
    private static let silentOutputWarningThreshold = 50
    /// Mic frame RMS above this is considered "there is real signal to hear".
    private static let inputRMSThreshold: Float = 0.01
    /// Output frame RMS below this is considered "silence".
    private static let outputRMSEpsilon: Float = 1e-4

    // MARK: - Public State

    /// `true` while the actor is processing; set to `false` after `stop()`.
    public private(set) var isActive = true

    // MARK: - Init

    public init(frameSize: Int32 = 256, filterLength: Int32 = 4096, sampleRate: Int32 = 16000) {
        self.frameSize = frameSize
        self.filterLength = filterLength
        self.sampleRate = sampleRate

        let count = Int(frameSize)
        micInt16 = [Int16](repeating: 0, count: count)
        farInt16 = [Int16](repeating: 0, count: count)
        outInt16 = [Int16](repeating: 0, count: count)
        outFloat = [Float](repeating: 0, count: count)

        resources = SpeexResources(
            frameSize: frameSize,
            filterLength: filterLength,
            sampleRate: sampleRate
        )
        if resources == nil {
            isActive = false
            logger.error("AECProcessorActor: Speex init failed -- AEC is inactive (pass-through mode)")
        }
    }

    // MARK: - Public API

    public func process(mic: TaggedAudioBuffer, farEnd: TaggedAudioBuffer) -> TaggedAudioBuffer {
        guard let res = resources else {
            if !isActive {
                logger.warning("AECProcessorActor.process() called after stop() -- returning mic pass-through")
            } else {
                logger.warning("AECProcessorActor.process() called with nil resources -- returning mic pass-through")
            }
            return passThrough(mic: mic)
        }

        let count = Int(frameSize)

        // Prepend leftover samples from the previous call, then loop over full
        // 256-sample chunks. Speex requires exactly frameSize samples per call;
        // the chunking loop ensures every input sample is eventually processed.
        //
        // Offset-cursor avoids O(n²) Array.removeFirst shifts.
        // farOffset advances in lockstep so each mic chunk gets the corresponding
        // far-end window (not the same first 256 samples repeated every iteration).
        let combined = remainder + mic.buffer.samples
        let farSamples = farEnd.buffer.samples
        var allProcessed: [Float] = []
        allProcessed.reserveCapacity(combined.count)

        var offset = 0
        var farOffset = 0

        while offset + count <= combined.count {
            fillInt16(&micInt16, from: Array(combined[offset ..< offset + count]), frameSize: count)
            let farSlice = farOffset < farSamples.count
                ? Array(farSamples[farOffset ..< min(farOffset + count, farSamples.count)])
                : []
            fillInt16(&farInt16, from: farSlice, frameSize: count)
            for i in 0 ..< count { outInt16[i] = 0 }

            speex_echo_cancellation(res.echo, &micInt16, &farInt16, &outInt16)
            speex_preprocess_run(res.pp, &outInt16)

            fillFloat32(&outFloat, from: outInt16)
            allProcessed.append(contentsOf: outFloat)

            trackSilentOutput(micFrame: combined[offset ..< offset + count], outFrame: outFloat)

            offset += count
            farOffset += count
        }

        // Carry sub-frame leftovers into the next call.
        remainder = Array(combined[offset...])

        let outBuffer = AudioBuffer(
            sampleRate: Double(sampleRate),
            channelCount: 1,
            samples: allProcessed,
            timestamp: mic.buffer.timestamp
        )
        return TaggedAudioBuffer(buffer: outBuffer, track: .microphone, timestamp: mic.timestamp)
    }

    public func stop() {
        guard isActive else { return }
        isActive = false
        resources = nil  // triggers SpeexResources.deinit
        remainder = []   // discard buffered remainder -- session is ending
        consecutiveSilentOutputFrames = 0
        hasLoggedSilentOutputWarning = false
        logger.info("AECProcessorActor stopped, Speex resources released")
    }

    // MARK: - Private Helpers

    /// Updates the silent-output diagnostic counter for one processed Speex frame
    /// and logs once (not per-frame) when the run crosses the threshold (A6 / #245).
    ///
    /// This does not change behaviour or fix any root cause -- it only makes a
    /// silent-WAV incident discoverable in logs instead of silent. A frame counts
    /// as "silent despite loud input" when the mic frame carried real signal
    /// (`inputRMSThreshold`) but the AEC output for that same frame was
    /// near-zero (`outputRMSEpsilon`).
    private func trackSilentOutput(micFrame: ArraySlice<Float>, outFrame: [Float]) {
        let micRMS = rmsFloat(micFrame)
        let outRMS = rmsFloat(outFrame)

        guard micRMS > Self.inputRMSThreshold, outRMS < Self.outputRMSEpsilon else {
            consecutiveSilentOutputFrames = 0
            return
        }

        consecutiveSilentOutputFrames += 1
        guard consecutiveSilentOutputFrames >= Self.silentOutputWarningThreshold, !hasLoggedSilentOutputWarning else {
            return
        }

        hasLoggedSilentOutputWarning = true
        logger.error(
            "AECProcessorActor: \(self.consecutiveSilentOutputFrames, privacy: .public) consecutive frames of near-zero output despite non-silent mic input (RMS \(micRMS, privacy: .public)) -- possible upstream far-end wiring bug or AEC over-cancellation (#245)"
        )
    }

    private func rmsFloat<S: Sequence>(_ samples: S) -> Float where S.Element == Float {
        var sum: Float = 0
        var count = 0
        for s in samples {
            sum += s * s
            count += 1
        }
        guard count > 0 else { return 0 }
        return (sum / Float(count)).squareRoot()
    }

    private func passThrough(mic: TaggedAudioBuffer) -> TaggedAudioBuffer {
        TaggedAudioBuffer(buffer: mic.buffer, track: .microphone, timestamp: mic.timestamp)
    }

    private func fillInt16(_ dest: inout [Int16], from src: [Float], frameSize: Int) {
        let limit = min(src.count, frameSize)
        for i in 0 ..< limit {
            dest[i] = Int16(clamping: Int(src[i] * 32767))
        }
        if limit < frameSize {
            for i in limit ..< frameSize { dest[i] = 0 }
        }
    }

    private func fillFloat32(_ dest: inout [Float], from src: [Int16]) {
        for i in 0 ..< src.count {
            dest[i] = Float(src[i]) / 32767.0
        }
    }
}

