import Accelerate
import Domain
import Foundation
import Logging

public struct VoiceEmbeddingActor: VoiceEmbeddingEngine, Sendable {
    public init() {}

    public func extract(from samples: [Float]) async -> [Float] {
        await Task.detached(priority: .userInitiated) {
            VoiceEmbedding.extract(from: samples)
        }.value
    }

    public func cosineSimilarity(_ a: [Float], _ b: [Float]) async -> Float {
        await Task.detached(priority: .userInitiated) {
            VoiceEmbedding.cosineSimilarity(a, b)
        }.value
    }
}

public enum VoiceEmbedding {
    private static let logger = AppLogger.for(category: "VoiceEmbedding")
    private static let embeddingDim = 64
    private static let fftSize = 512
    private static let hopSize = 256
    private static let numMelBands = 40
    private static let sampleRate: Float = 16000
    /// Wraps the C FFT setup so vDSP_destroy_fftsetup is called deterministically at process exit.
    private final class FFTSetupBox {
        let setup: OpaquePointer
        init?(_ log2n: vDSP_Length) {
            guard let s = vDSP_create_fftsetup(log2n, FFTRadix(kFFTRadix2)) else { return nil }
            setup = s
        }

        deinit { vDSP_destroy_fftsetup(setup) }
    }

    // Safety: created once at process load time, then only read concurrently.
    private nonisolated(unsafe) static let fftSetupBox: FFTSetupBox? = FFTSetupBox(vDSP_Length(9))

    public static func extract(from samples: [Float]) -> [Float] {
        guard samples.count >= fftSize else {
            return [Float](repeating: 0, count: embeddingDim)
        }

        let melEnergies = computeMelSpectrogram(samples)
        return averageAndProject(melEnergies)
    }

    public static func cosineSimilarity(_ a: [Float], _ b: [Float]) -> Float {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        var dot: Float = 0, normA: Float = 0, normB: Float = 0
        vDSP_dotpr(a, 1, b, 1, &dot, vDSP_Length(a.count))
        vDSP_svesq(a, 1, &normA, vDSP_Length(a.count))
        vDSP_svesq(b, 1, &normB, vDSP_Length(b.count))
        let denom = sqrt(normA) * sqrt(normB)
        guard denom > 0 else { return 0 }
        return dot / denom
    }

    private static func computeMelSpectrogram(_ samples: [Float]) -> [[Float]] {
        let numFrames = (samples.count - fftSize) / hopSize + 1
        guard numFrames > 0 else { return [] }

        var frames: [[Float]] = []
        for i in 0 ..< min(numFrames, 200) {
            let start = i * hopSize
            let end = start + fftSize
            guard end <= samples.count else { break }
            let frame = Array(samples[start ..< end])
            let power = computePowerSpectrum(frame)
            let mel = applyMelFilterbank(power)
            frames.append(mel)
        }
        return frames
    }

    private static func computePowerSpectrum(_ frame: [Float]) -> [Float] {
        var windowed = frame
        var window = [Float](repeating: 0, count: fftSize)
        vDSP_hann_window(&window, vDSP_Length(fftSize), Int32(vDSP_HANN_NORM))
        vDSP_vmul(frame, 1, window, 1, &windowed, 1, vDSP_Length(fftSize))

        let log2n = vDSP_Length(log2(Float(fftSize)))
        guard let setup = Self.fftSetupBox?.setup else {
            return [Float](repeating: 0, count: fftSize / 2)
        }

        var realPart = [Float](repeating: 0, count: fftSize / 2)
        var imagPart = [Float](repeating: 0, count: fftSize / 2)
        realPart.withUnsafeMutableBufferPointer { realBuf in
            imagPart.withUnsafeMutableBufferPointer { imagBuf in
                var splitComplex = DSPSplitComplex(realp: realBuf.baseAddress!, imagp: imagBuf.baseAddress!)
                windowed.withUnsafeBufferPointer { ptr in
                    ptr.baseAddress!.withMemoryRebound(to: DSPComplex.self, capacity: fftSize / 2) { complexPtr in
                        vDSP_ctoz(complexPtr, 2, &splitComplex, 1, vDSP_Length(fftSize / 2))
                        vDSP_fft_zrip(setup, &splitComplex, 1, log2n, FFTDirection(kFFTDirection_Forward))
                    }
                }
            }
        }

        var power = [Float](repeating: 0, count: fftSize / 2)
        realPart.withUnsafeMutableBufferPointer { realBuf in
            imagPart.withUnsafeMutableBufferPointer { imagBuf in
                var split = DSPSplitComplex(realp: realBuf.baseAddress!, imagp: imagBuf.baseAddress!)
                vDSP_zvmags(&split, 1, &power, 1, vDSP_Length(fftSize / 2))
            }
        }
        return power
    }

    private static func applyMelFilterbank(_ power: [Float]) -> [Float] {
        let nBins = power.count
        var mel = [Float](repeating: 0, count: numMelBands)
        let binsPerBand = max(1, nBins / numMelBands)
        for band in 0 ..< numMelBands {
            let start = band * binsPerBand
            let end = min(start + binsPerBand, nBins)
            guard start < end else { continue }
            var sum: Float = 0
            vDSP_sve(Array(power[start ..< end]), 1, &sum, vDSP_Length(end - start))
            mel[band] = log(max(sum, 1e-10))
        }
        return mel
    }

    private static func averageAndProject(_ frames: [[Float]]) -> [Float] {
        guard !frames.isEmpty else { return [Float](repeating: 0, count: embeddingDim) }

        var avg = [Float](repeating: 0, count: numMelBands)
        var variance = [Float](repeating: 0, count: numMelBands)

        for frame in frames {
            for i in 0 ..< min(frame.count, numMelBands) {
                avg[i] += frame[i]
            }
        }
        var count = Float(frames.count)
        vDSP_vsdiv(avg, 1, &count, &avg, 1, vDSP_Length(numMelBands))

        for frame in frames {
            for i in 0 ..< min(frame.count, numMelBands) {
                let diff = frame[i] - avg[i]
                variance[i] += diff * diff
            }
        }
        vDSP_vsdiv(variance, 1, &count, &variance, 1, vDSP_Length(numMelBands))

        var embedding = avg + variance
        if embedding.count < embeddingDim {
            embedding += [Float](repeating: 0, count: embeddingDim - embedding.count)
        } else if embedding.count > embeddingDim {
            embedding = Array(embedding.prefix(embeddingDim))
        }

        var norm: Float = 0
        vDSP_svesq(embedding, 1, &norm, vDSP_Length(embeddingDim))
        norm = sqrt(norm)
        if norm > 0 {
            vDSP_vsdiv(embedding, 1, &norm, &embedding, 1, vDSP_Length(embeddingDim))
        }

        return embedding
    }
}

